var hrSecurityUtil = new global.HRSecurityUtils();
var hrProfileGR = new GlideRecord("sn_hr_core_profile");
hrProfileGR.addNotNullQuery("source");
hrProfileGR.query();
while (hrProfileGR.next())
	hrSecurityUtil.updateIntegrationSourceFieldInSysUser(hrProfileGR.getValue("user"),hrProfileGR.getValue("source"));
